package org.eclipse.rdf4j.query.algebra.helpers;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.ArrayList;
import java.util.Set;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class OutputFrameOwnershipTest {
	@Test
	void derivesFromTheFactsOwnInputEvenWhenAskedThroughADifferentReceiver() {
		var root = new SingletonSet();
		var vf = SimpleValueFactory.getInstance();
		var bindings = new MapBindingSet();
		var anchor = vf.createIRI("urn:original");
		bindings.addBinding("s", anchor);
		var source = QueryAlgebraBindingAnalysis.withBindingValues(root, bindings);
		var facts = source.outputFacts(root, source.rootContext());
		bindings.setBinding("s", vf.createIRI("urn:different"));
		var other = QueryAlgebraBindingAnalysis.withBindingValues(root, bindings);
		assertSame(anchor, other.rootContext().withOutput(facts).fixedValues().get("s"));
		assertSame(anchor, source.rootContext().withOutput(facts).fixedValues().get("s"));
		assertSame(facts, source.outputFacts(root, source.rootContext()));
	}

	@Test
	void invalidationChangesNewFramesButPreviouslyExportedFactsStayImmutable() {
		var pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		var root = new Projection(pattern, new ProjectionElemList(new ProjectionElem("s", "before")));
		var analysis = QueryAlgebraBindingAnalysis.withBindingValues(root, EmptyBindingSet.getInstance());
		var input = analysis.rootContext();
		var before = analysis.outputFacts(root, input);
		var oldFrame = input.withOutput(before);

		root.setProjectionElemList(new ProjectionElemList(new ProjectionElem("s", "after")));
		analysis.invalidate(root);
		var after = analysis.outputFacts(root, input);
		assertNotSame(before, after);
		assertEquals(Set.of("after"), input.withOutput(after).guaranteedNames());
		assertSame(oldFrame, input.withOutput(before));
		assertEquals(Set.of("before"), oldFrame.guaranteedNames());
	}

	@Test
	void concurrentFirstConsumersObserveOneCompletedFrame() throws Exception {
		var root = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		var analysis = QueryAlgebraBindingAnalysis.withBindingValues(root, EmptyBindingSet.getInstance());
		var input = analysis.rootContext();
		var facts = analysis.outputFacts(root, input);
		var barrier = new CyclicBarrier(8);
		try (var pool = Executors.newFixedThreadPool(8)) {
			var results = new ArrayList<Future<QueryAlgebraBindingAnalysis.ReadOnlyContext>>();
			for (int i = 0; i < 8; i++) {
				results.add(pool.submit(() -> {
					barrier.await();
					return input.withOutput(facts);
				}));
			}
			var first = results.getFirst().get();
			assertEquals(Set.of("s", "p", "o"), first.guaranteedNames());
			for (var result : results) {
				assertSame(first, result.get());
			}
		}
	}
}
